// Missing entries for Surahs 46-50

MIROIR["46:5"] = {
  reference: "46:5",
  theme: ["confiance", "égarement", "invocation"],
  emotion: "Clarté, discernement",
  difficulty: "débutant",
  relatedNames: ["Al-Haqq", "Al-Mujib"],
  mirrorVersion: `« Et qui est plus égaré que celui qui invoque en dehors d'Allah ce qui ne peut lui répondre ni maintenant ni plus tard ? » Le miroir me renvoie cette question comme un diagnostic de mes dépendances. Qu'est-ce que j'invoque en dehors d'Allah ? Vers quoi me tournent mes espérances, mes attentes, mes supplications silencieuses ? L'invocation n'est pas seulement verbale — elle est l'orientation du cœur. Quand j'attends tout d'une personne, d'une situation, d'un résultat, j'invoque. Et ce verset me dit : ces choses ne peuvent pas répondre. Pas maintenant, pas plus tard. Elles sont muettes face à mes besoins profonds. Seul Allah entend et répond.`,
  reflection: `L'égarement n'est pas seulement le rejet de Dieu — c'est l'investissement du cœur dans ce qui ne peut pas le satisfaire.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Wa man adallu mimman yad'u min duni Allahi man la yastajibu lahu ila yawmi al-qiyamah » — qui est plus égaré que celui qui invoque en dehors d'Allah ce qui ne peut lui répondre jusqu'au Jour de la Résurrection." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Qu'est-ce que j'attends en ce moment qui ne peut pas me donner ce que je cherche ? Le miroir me montre mes fausses divinités : l'approbation, le succès, le confort." },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Allah répond toujours — mais pas toujours comme je l'attends. Son silence est parfois la réponse. Son délai est parfois la miséricorde." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Toute chose dans l'univers invoque son Créateur par son existence même. Seul l'être humain peut choisir d'invoquer ce qui n'existe pas vraiment." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Quand le cœur réalise que seul Allah répond, il cesse de courir après les échos et trouve la paix dans la Source." }
  ],
  munajat: `Ya Allah, je T'invoque car Toi seul réponds. Détourne mon cœur de ce qui ne peut pas me satisfaire et oriente-le vers Toi.`
};

MIROIR["46:6"] = {
  reference: "46:6",
  theme: ["jugement", "idolâtrie", "désaveu"],
  emotion: "Effroi, prise de conscience",
  difficulty: "débutant",
  relatedNames: ["Al-Hasib", "Al-Muhit"],
  mirrorVersion: `« Et quand les gens seront rassemblés, ils seront leurs ennemis et ils nieront leur adoration. » Le miroir me montre le jour où mes idoles se retourneront contre moi. Ce que j'ai aimé en dehors d'Allah — l'argent, le statut, les plaisirs — prendra vie ce jour-là pour dire : « Je ne t'ai jamais demandé de m'adorer. » Mes idoles sont innocentes de mon égarement. C'est moi qui les ai divinisées. Le miroir me demande : quels ennemis suis-je en train de nourrir aujourd'hui ?`,
  reflection: `L'idole n'est pas responsable de mon idolâtrie — c'est mon cœur qui a projeté sur elle ce qui n'appartenait qu'à Allah.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Wa idha hushira al-nasu kanu lahum a'da'an wa kanu bi-'ibadatihim kafirin » — quand les gens seront rassemblés, ils seront leurs ennemis et ils nieront leur adoration." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Quels « dieux » ai-je créés dans ma vie ? Et comment réagiront-ils quand je les rencontrerai vraiment ? Le miroir anticipe le désaveu." },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Ceux qui ont adoré Allah ne seront jamais trahis — Lui seul reste fidèle au-delà de la mort." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Chaque chose créée retourne à son Créateur. Seul le Créateur peut être l'objet légitime de l'adoration." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Le désaveu des idoles est la dernière chance de voir la vérité — mais ce jour-là, il sera trop tard pour changer." }
  ],
  munajat: `Ya Allah, libère-moi de mes idoles avant qu'elles ne se retournent contre moi. Fais que Tu sois le seul objet de mon adoration.`
};

MIROIR["46:7"] = {
  reference: "46:7",
  theme: ["vérité", "désaveu", "orgueil"],
  emotion: "Tristesse, lucidité",
  difficulty: "débutant",
  relatedNames: ["Al-Haqq", "An-Nur"],
  mirrorVersion: `« Et quand Nos versets clairs leur sont récités, ceux qui ont mécru disent de la vérité quand elle leur est venue : « C'est de la magie manifeste. » » Le miroir me montre la résistance du cœur face à la vérité. Ce n'est pas que la vérité soit obscure — c'est que l'orgueil la rend invisible. Les mécréants n'ont pas nié parce que le Coran était incompréhensible — ils ont nié parce qu'il dérangeait leur position. Le miroir m'interroge : quelle vérité est-ce que je qualifie de « magie » pour ne pas avoir à la suivre ?`,
  reflection: `Le rejet de la vérité n'est pas une question d'intelligence — c'est une question de soumission du cœur.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Wa idha tutla 'alayhim ayatuna bayyinat qala alladhina kafaru lil-haqqi lamma ja'ahum hadha sihrun mubin » — ceux qui ont mécru disent de la vérité : c'est de la magie manifeste." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Quelle partie de la révélation me dérange ? Quelle injonction est-ce que j'évite en la qualifiant d'obsolète ou d'exagérée ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "La vérité qui dérange est souvent celle dont j'ai le plus besoin." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La vérité existe indépendamment de mon acceptation. La nier ne l'efface pas — elle m'éloigne seulement de la réalité." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Quand le cœur cesse de se défendre contre la vérité, il découvre que cette vérité était toujours son ami." }
  ],
  munajat: `Ya Haqq, ne permets pas que je rejette Ta vérité par orgueil. Ouvre mon cœur à ce qui me dérange mais me guérit.`
};

MIROIR["46:8"] = {
  reference: "46:8",
  theme: ["mensonge", "révélation", "justice"],
  emotion: "Sérénité, confiance",
  difficulty: "débutant",
  relatedNames: ["As-Sadiq", "Al-'Adl"],
  mirrorVersion: `« Ou bien ils disent : « Il l'a inventé. » Dis : « Si je l'ai inventé, vous ne pouvez rien pour moi contre Allah. » » Le miroir me montre la fausseté des accusations. Le Prophète ne s'est pas défendu par des arguments — il s'est remis à Allah. C'est la posture du croyant face au mensonge : je ne peux pas vous convaincre, mais Allah sait. L'accusation d'invention est la réponse de ceux qui refusent d'écouter. Le miroir m'invite à la même confiance : je ne dois pas prouver ma sincérité à ceux qui ont décidé de ne pas croire.`,
  reflection: `La vérité n'a pas besoin d'être défendue — elle a besoin d'être vécue. Allah est le témoin suffisant.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Am yaqulun iftarahu qul ini iftaraytuhu fa-la tamlikuna li min Allahi shay'an » — dis : si je l'ai inventé, vous ne pouvez rien pour moi contre Allah." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Est-ce que je cherche à me justifier face à ceux qui ne croiront jamais ? Le miroir m'invite à lâcher cette besoin de validation." },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Celui qui est accusé à tort n'a pas besoin de se défendre — sa conscience et son Seigneur lui suffisent." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La vérité finit toujours par triompher — pas toujours dans cette vie, mais certainement dans l'autre." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Le silence face à l'accusation injuste est une forme de confiance en Allah." }
  ],
  munajat: `Ya Allah, quand on m'accuse à tort, rappelle-moi que Tu sais. Donne-moi la paix du cœur qui n'a pas besoin de se justifier.`
};

MIROIR["46:9"] = {
  reference: "46:9",
  theme: ["humilité", "prophète", "exemple"],
  emotion: "Révérence, modestie",
  difficulty: "débutant",
  relatedNames: ["An-Nabi", "Al-Uswa"],
  mirrorVersion: `« Dis : Je ne suis pas une innovation parmi les messagers, et je ne sais pas ce qu'on fera de moi ni de vous. » Le miroir me montre l'humilité du Prophète lui-même. Même le Messager d'Allah ne connaissait pas son destin final — il vivait dans la confiance, pas dans la certitude du résultat. Cette humilité est un enseignement. Je ne sais pas ce qui m'attend. Je ne sais pas si je serai sauvé. Mais je marche. Le miroir me libère de l'arrogance spirituelle qui prétend « savoir » où je vais. Je marche, j'espère, je me confie.`,
  reflection: `Le Prophète était le plus savant des hommes — mais il ne savait pas l'avenir. Cette ignorance était une forme de confiance en Allah.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Qul ma kuntu bid'an min al-rusuli wa ma adri ma yuf'alu bi wa la bikum » — dis : je ne suis pas une innovation parmi les messagers, et je ne sais pas ce qu'on fera de moi ni de vous." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Est-ce que je prétends savoir mon avenir spirituel ? Le miroir m'invite à l'humilité du « je ne sais pas »." },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Ne pas savoir l'avenir n'est pas une faiblesse — c'est l'espace où la confiance en Allah se déploie." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "Aucune créature ne connaît son avenir — c'est le privilège exclusif du Créateur." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Le « je ne sais pas » du Prophète était la forme la plus haute de confiance : marcher sans voir, aimer sans garantie." }
  ],
  munajat: `Ya Rabb, je ne sais pas ce qui m'attend. Mais je sais que Tu es bon. Apprends-moi à marcher dans l'obscurité, guidé par Ta lumière.`
};

MIROIR["46:10"] = {
  reference: "46:10",
  theme: ["témoignage", "livre", "guidance"],
  emotion: "Espérance, certitude",
  difficulty: "intermédiaire",
  relatedNames: ["Al-Kitab", "Al-Huda"],
  mirrorVersion: `« Dis : Avez-vous réfléchi ? Si ceci vient d'Allah et que vous l'avez mécru, et qu'un témoin parmi les fils d'Israël en a témoigné... » Le miroir me montre la cohérence de la révélation à travers les âges. Le Coran n'est pas une innovation — il est la confirmation de ce qui l'a précédé. Un témoin des Écritures antérieures peut reconnaître la même source. Le miroir m'invite à voir l'unité de la révélation divine à travers les siècles. Ce n'est pas une religion nouvelle — c'est la religion éternelle qui se renouvelle.`,
  reflection: `La vérité n'est pas nouvelle — elle est redécouverte. Chaque révélation confirme les précédentes.`,
  tajalli: [
    { label: "La Forme", ar: "الأصل", color: "var(--gold)", text: "« Qul ara'aytum in kana min 'indi Allahi wa kafartum bihi wa shahida shahidun min bani Isra'ila 'ala mithlihi » — si ceci vient d'Allah et qu'un témoin parmi les fils d'Israël en a témoigné..." },
    { label: "Le Reflet", ar: "المرصاد", color: "var(--mirror)", text: "Est-ce que je reconnais la continuité de la révélation ? Ou est-ce que je vois chaque message comme isolé ?" },
    { label: "L'Inversion", ar: "القلب", color: "var(--purple)", text: "Ceux qui reconnaissent la vérité dans une écriture la reconnaîtront dans l'autre — car la source est unique." },
    { label: "L'Universel", ar: "الكون", color: "#34d399", text: "La révélation est un fleuve qui coule à travers l'histoire — changeant de lit mais jamais de source." },
    { label: "Le Secret", ar: "السر", color: "#fb7185", text: "Celui qui reconnaît la vérité dans le Coran la reconnaîtra partout où elle apparaît — car la vérité a un goût unique." }
  ],
  munajat: `Ya Rabb, fais que je reconnaisse Ta voix dans toutes Ses manifestations. Unifie ma vision de Ta révélation éternelle.`
};

